/*
 * NETWORK_$RTNHDR - give back a header page NETWORK_$GETHDR handed out
 *
 * Original address: 0x00E0F414
 * Size: 74 bytes (0x00E0F414 .. 0x00E0F45D)
 * Generated by: Claude Opus 5.5
 *
 * Frame: (0x8,A6) va_ptr.  A5 = the NETWORK segment (0xE248FC).
 *
 * Blocks:
 *   0x00E0F422-0x00E0F42C  *va_ptr is the shared header page
 *                          (NETWORK_$HDR_PAGE, +0x30C)?
 *   0x00E0F42E-0x00E0F446  no: pa = NETBUF_$RTNVA(va_ptr), then
 *                          MMAP_$FREE(pa >> 10) returns the page
 *   0x00E0F448-0x00E0F44E  yes: release ML_LOCK_NET_IO (0x18)
 *
 * The copy of the address kept in D2 (0x00E0F438) is never used.
 */

#include "network/network_internal.h"
#include "netbuf/netbuf.h"      /* NETBUF_$RTNVA */
#include "mmap/mmap.h"          /* MMAP_$FREE */
#include "ml/ml.h"              /* ML_$UNLOCK, ML_LOCK_NET_IO */

void NETWORK_$RTNHDR(uint32_t *va_ptr)
{
    uint32_t pa;                        /* D0 */

    /* 0x00E0F422-0x00E0F42C */
    if (*va_ptr != NETWORK_$HDR_PAGE) {
        /* 0x00E0F42E-0x00E0F446 */
        pa = NETBUF_$RTNVA(va_ptr);
        MMAP_$FREE(pa >> 10);
    } else {
        /* 0x00E0F448-0x00E0F44E */
        ML_$UNLOCK(ML_LOCK_NET_IO);
    }
}
